"""
stage_visuals.py: the rules of stage 5 (tables and figures), the decisions the stage
used to hold as fixed values in its code (owner request 2026-11-19, A1:
"Die festen Werte werden Regeln mit dem heutigen Wert als Standard"). Their
values stand in the default profile's rules.json; a profile that decides
otherwise says so in its own. The stage reads each where it decides, when it
runs (`rules.get`), so that a changed value is the next run's.

Author: Felix Vossel
"""
from .kit import rule

# The group of these rules on the tab "stages".
GROUP = "Stage 5: tables and figures"

RULES: tuple = (
    rule('vision_max_attempts', "stages", GROUP, 'whole',
         'How many times a request to the vision model is sent in all, the first time included, when the server fails or the reply is not the one answer asked for. A request whose reply is cut off at its limit is asked again with more room and a stronger penalty for repetition. A request the server refuses is never repeated. A larger value tries longer before a table or figure is left without content; a smaller one gives up sooner. The request that reads a page of a scan without text layer follows it too. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         least=1, most=20, where='vision.py (call_vision)',
         title='Attempts per vision request'),
    rule('figure_temperature', "stages", GROUP, 'number',
         'The sampling temperature of the request that describes a figure, and of every other vision request that has none of its own. A higher value gives freer descriptions, a lower one steadier ones. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         least=0, most=2, where='vision.py (call_vision)',
         title='Temperature for figures'),
    rule('table_temperature', "stages", GROUP, 'number',
         'The sampling temperature of the request that transcribes a table. A table must be copied as it is, so the value is low; a higher value lets the copy vary. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         least=0, most=2, where='process.py (process_table)',
         title='Temperature for tables'),
    rule('vision_max_tokens', "stages", GROUP, 'whole',
         'The most tokens the reply of a table or figure request may have. A table whose reply is cut off is asked once more with more room and then read in strips. A larger value gives room for large tables and raises the largest request the vision server has to be started for. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         least=256, most=262144, where='vision.py (call_vision), config.py (max_request_tokens)',
         title='Reply room of vision requests'),
    rule('vision_tokens_per_word', "stages", GROUP, 'number',
         "How many tokens one word counts as when the size of a vision request is estimated, for the check of the vision server's window before the stage starts. An over-estimate costs a little memory of the server; an under-estimate lets the check pass a request that does not fit. Takes effect the next time the stage is checked or started.",
         least=0.5, most=10, where='config.py (max_request_tokens); preprocessing/page_text_without_layer.py (page_request_tokens); estimate.py',
         title='Tokens per word (vision)'),
    rule('vision_retry_penalties', "stages", GROUP, 'map',
         'The penalty for repetition sent with the later attempts of a vision request (the first runs without one), as numbers from 1 up: second_attempt after the first failed, third_attempt after the second, later_attempts after every further one. A table legitimately repeats bars, dashes and years, so a high penalty makes it unwritable; at 1.8 answers broke off after ten tokens. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         of='number', where='vision.py (call_vision)',
         title='Penalties for repetition on retry'),
    rule('strip_ink_contrast', "stages", GROUP, 'whole',
         'How many grey levels (of 255) darker than what its column and its row hold in most places a point of a table picture must be to count as writing, when the picture is cut into strips at a blank row. A smaller value counts faint marks as writing; a larger one only dark writing. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         least=1, most=255, where='strips.py (ink_rows)',
         title='Contrast of writing'),
    rule('strip_blank_pixels', "stages", GROUP, 'whole',
         'The most points of writing a pixel row of a table picture may have and still be a blank row to cut the picture at; it lets the specks of a scan pass. A larger value finds more places to cut and may cut through small writing. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         least=0, most=100, where='strips.py (cut_at)',
         title='Specks in a blank row'),
    rule('strip_rule_drift', "stages", GROUP, 'whole',
         'How many pixels a vertical rule of a table may drift, because a scan is tilted, and still be taken as a rule and not as writing. A larger value takes more tilted lines for rules. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         least=0, most=20, where='strips.py (ink_rows)',
         title='Tilt of a rule'),
    rule('read_cut_tables_in_strips', "stages", GROUP, 'switch',
         'On: a table whose reply is cut off even with the most room it can be given is cut at a blank pixel row into strips, and each strip is read. Off: such a table has no content, and the stage says it was cut off. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         where='process.py (process_table)',
         title='Read large tables in strips'),
    rule('table_min_coverage', "stages", GROUP, 'number',
         "The share of the content words and numbers of the PDF's own text of a table that must stand in its transcription. A table below it is asked again and the better reading is kept. A larger value asks more tables again. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.",
         least=0, most=1, where='process.py (_assess_table), qa.py (assess)',
         title='Least coverage of a table'),
    rule('table_max_duplication', "stages", GROUP, 'number',
         'The share of the rows of a transcribed table that may repeat an earlier row. A runaway grid repeats rows; above this share the table is asked again. A smaller value asks more tables again. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         least=0, most=1, where='process.py (_assess_table), qa.py (assess)',
         title='Most repeated rows of a table'),
    rule('table_min_source_tokens', "stages", GROUP, 'whole',
         "The fewest content words and numbers the PDF's own text of a table must hold for its coverage to be measured at all. A table with less, such as a table that is only a picture, is not checked, and the stage says so. A larger value leaves more tables unchecked. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.",
         least=1, most=200, where='process.py (_assess_table), qa.py (coverage)',
         title='Least text to measure a table'),
    rule('table_unreadable_shared_below', "stages", GROUP, 'number',
         "Together with the next rule: the PDF's own text of a table is no measure if less than this share of the transcription's content stands in it and also few of its words occur elsewhere in the document, as with a sideways scan whose text layer is upside down. A larger value takes more texts for unreadable. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.",
         least=0, most=1, where='process.py (_assess_table), qa.py (unreadable)',
         title='Overlap showing an unreadable text layer'),
    rule('table_unreadable_known_below', "stages", GROUP, 'number',
         "The share of the words of the PDF's own text of a table that must occur in the rest of the document for the text to count as readable. Below it, and below the overlap of the previous rule, the text is ignored when the table is judged. A larger value takes more texts for unreadable. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.",
         least=0, most=1, where='process.py (_assess_table), qa.py (unreadable)',
         title='Known words showing an unreadable text layer'),
    rule('table_retry_temperature', "stages", GROUP, 'number',
         'The sampling temperature of the further reading of a table that failed the check. A higher value makes the answer differ more from the first. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         least=0, most=2, where='process.py (process_table)',
         title='Temperature of the table reread'),
    rule('table_retry_penalty', "stages", GROUP, 'number',
         'The penalty for repetition of the further reading of a table that failed the check; it pushes the model away from repeating rows. A larger value pushes harder and may make a table unwritable. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         least=1.0, most=2.0, where='process.py (process_table)',
         title='Penalty of the table reread'),
    rule('table_qa_retries', "stages", GROUP, 'whole',
         'How many times a table that fails the check is transcribed again; the better reading (one that passes, else the one with higher coverage) is kept. 0: the first reading stands. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         least=0, most=5, where='process.py (process_table)',
         title='Table rereads'),
    rule('collapse_stutter_rows', "stages", GROUP, 'switch',
         'On: where a table fails the check, runs of identical rows one after the other are written once. A table that passes is never touched. Off: a table that fails is kept as it was read. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         where='process.py (process_table)',
         title='Collapse stuttered rows'),
    rule('qa_token_min_letters', "stages", GROUP, 'whole',
         "The fewest letters a word needs to count as content when the transcription of a table is compared with the PDF's own text. Numbers always count; shorter words and punctuation are ignored, so '24V' and '24 V' do not differ. A larger value compares fewer words. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.",
         least=1, most=10, where='qa.py (salient_tokens)',
         title='Shortest word of the check'),
    rule('qa_word_min_letters', "stages", GROUP, 'whole',
         "The fewest letters a word needs when the words of a PDF's own text of a table are compared with the rest of the document to judge whether that text is readable. Numbers and stray letter pairs decide nothing. A smaller value lets more small words decide. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.",
         least=1, most=10, where='qa.py (words)',
         title='Shortest word of the readability test'),
    rule('request_blank_words', "stages", GROUP, 'map',
         'The words written into a table or figure request where a piece of information is missing: section_title for the title of the section, caption for a caption (also that of the table before), head for the head of the table before, between for the text between two tables. The request is read in English, so these are English words. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         of='text', where='process.py (process_table, process_figure)',
         title='Words for missing items'),
    rule('table_continuation_page_gap', "stages", GROUP, 'whole',
         'How many pages after a table another table may begin and still be asked whether it continues the first. 0: only on the same page; 1: the same page or the next. A larger value asks about more tables. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         least=0, most=5, where='continuation.py (links)',
         title='Page gap of continued tables'),
    rule('between_tables_words', "stages", GROUP, 'map',
         'How the pieces between a table and the table that may continue it are written into the request: figure_with_caption for a figure with its caption ({caption} stands for the caption), figure for a figure without one, heading for a heading ({title} stands for its words). The request is read in English, so these are English words. Takes effect for the tables and figures stage 5 reads next; one already read is not read again.',
         of='text', where='continuation.py (_said)',
         title='Words for pieces between tables'),
)
